WITH data(id,aid_code,name,provider,eligibility,benefit,apply_instruction) AS (VALUES ('d4000000-0000-4000-8000-000000000001'::uuid, 'TN-DCE-02', 'EVR Nagammai Scholarship, Tamil Nadu', 'Directorate of Collegiate Education, Government of Tamil Nadu', 'This scholarship is applicable only for girl students who are pursuing postgraduate degree courses in Arts and Science from a recognised college in Tamil Nadu.', 'Variable financial assistance', 'Apply offline through the Directorate of Collegiate Education'),
('d4000000-0000-4000-8000-000000000002'::uuid, 'TN-DCE-03', 'CENTRAL SECTOR SCHEME OF SCHOLARSHP (CSSS)', 'Ministry of Human Resource Development (MHRD)', 'Applied for UG first year students. Minimum qualification above 60 percentage (Higher Secondary) Community and Subject Based', 'UG yearly INR 10,000 PG YEARLY INR 20,000', 'Apply online www.scholarships.gov.in'),
('d4000000-0000-4000-8000-000000000003'::uuid, 'TN-DCE-04', 'Scholarship to Son and Daughter of Differently Abled Persons, Tamil Nadu', 'Commissionerate for Welfare of Differently Abled, Government of Tamil Nadu', '1. The wards of any differently abled person holding the Identity card issued by the Welfare Board of Differently Abled can apply for this scholarship. 2. The scholarship is applicable for studies from class 11th to Postgraduate level (including ITI/Polytechnic diploma courses).', 'Financial assistance of up to INR 6,000', 'Apply offline through concerned District Office of Differently Abled Welfare'),
('d4000000-0000-4000-8000-000000000004'::uuid, 'TN-DCE-05', 'Scholarship for Differently Abled Students from Class 9th Onwards, Tamil Nadu', 'Commissionerate for Welfare of Differently Abled, Government of Tamil Nadu', '1.The scholarship is open to differently abled students studying in class 9th to postgraduate level (including Vocational, Professional, Medical and Engineering courses) 2. The applicant should have scored at least 40% marks in the previous qualifying examination.', 'Financial assistance of up to INR 7,000 per annum', 'Apply offline through concerned District Office of Differently Abled Welfare'),
('d4000000-0000-4000-8000-000000000005'::uuid, 'TN-DCE-07', 'Free Education Schemes for BC, MBC & DNC students, Tamil Nadu', 'Department of Backward Classes and Most Backward Classes and Minority Welfare, Government of Tamil Nadu', 'The scholarship is open to students belonging to BC/MBC/DNC category who are pursuing a 3-year degree or polytechnic diploma course or professional degree course. The annual income of the family should not be more than INR 50,000.', 'Tuition fees, examination fees, special fees and other compulsory fees up to INR 10,000 (approximate)', 'Apply through the district office of Backward Classes and Minority Welfare'),
('d4000000-0000-4000-8000-000000000006'::uuid, 'TN-DCE-09', 'Thanthai Periyar Memorial Award, Tamil Nadu', 'Department of Backward Classes and Most Backward Classes and Minority Welfare, Government of Tamil Nadu', 'The top two boys and two girls of each district in Tamil Nadu who have scored highest marks in class 10th and are pursuing a Polytechnic diploma can apply for this scholarship.The scheme is open only for BC/MBC/DNC students', 'INR 3,000 per annum for three years', 'Apply through the district office of Backward Classes and Minority Welfare'),
('d4000000-0000-4000-8000-000000000007'::uuid, 'TN-DCE-10', 'Perarignar Anna Memorial Award, Tamil Nadu', 'Department of Backward Classes and Most Backward Classes and Minority Welfare, Government of Tamil Nadu', 'The top two boys and two girls of each district in Tamil Nadu who have scored highest marks in class 12th and are pursuing a Professional degree course (medical, engineering, law, etc.) can apply for this scholarship. The scheme is open only for BC/MBC/DNC students', 'INR 3,000 per annum for four years or till the normal completion of course', 'Apply through the district office of Backward Classes and Minority Welfare'),
('d4000000-0000-4000-8000-000000000008'::uuid, 'TN-DCE-13', 'Free Education Schemes for SC / ST students, Tamil Nadu', 'Adi Dravidar and Tribal Welfare Department', '1000 boys and 1000 girls belonging to Adi Dravidar, Tribal and Adi Dravidar converted to Christianity communities in the order of their marks in plus 2 Public examination are given an award of Rs.3,000 each per annum for a period of 5 years, if they continue education', 'Chief Minister Merit Award- Given Rs.3000/- per annum for 5 years', 'DADWO through the Educational Institutions.'),
('d4000000-0000-4000-8000-000000000009'::uuid, 'TN-DCE-14', 'Post metric scholarship for BC / MBC/ DNC', 'bcmbcmw.tn.gov.in', 'Backward Classes -Parental annual income should not exceed Rs 2.50 lakh. Most Backward Classes and Denotified Communities No Condition.', 'Under Free Education scholarship (Degree) scheme, students of Backward Classes, Most Backward Classes and Denotified Communities studying in three year Degree Courses in Government and Government Aided Arts and Science colleges are sanctioned special fee and non-refundable compulsory fee as prescribed by the Government (Tuition fee of students studying in three year Degree Courses in Government and Government Aided Arts and Science colleges has been waived).', 'BC, MBC and DNC College students can collect their BC, MBC, and DNC Scholarship applications from their Institutions and submit the duly filled-in applications with the relevant documents to the Institutions.'),
('d4000000-0000-4000-8000-000000000010'::uuid, 'TN-DCE-15', 'Post metric scholarship for SC/ST', 'ADI DRAVIDAR WELFARE DEPARTMENT', 'Self-Finance College Government Approved Course Re-imbursement Fees', 'All SC ST students in self-financing Colleges', 'Applied Institution to be added to the portal - TNSSP'))
